#!/usr/bin/env node
/**
 * Maskable icon is generated by scripts/generate-brand-assets.mjs (paw + label, safe zone).
 * This script is kept for build compatibility — no-op when output already exists.
 */
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const out = join(dirname(fileURLToPath(import.meta.url)), '../public/images/icon-maskable-512.png');

if (existsSync(out)) {
  console.log('Maskable icon already built by brand:assets —', out);
  process.exit(0);
}

console.warn('Run npm run brand:assets to generate icon-maskable-512.png');
process.exit(0);
